-- ------------------------------------------------------------------------------
-- CẬP NHẬT SM_SEQUENCER (Đảm bảo dải sinh tự động tiếp theo > 100000)
-- ------------------------------------------------------------------------------
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'CATEGORY_SEQ_NEXT_VAL';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'category_description_seq';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'PRODUCT_SEQ_NEXT_VAL';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'product_description_seq';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'PRODUCT_AVAIL_SEQ_NEXT_VAL';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'PRODUCT_PRICE_SEQ_NEXT_VAL';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'product_price_description_seq';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'CUSTOMER_SEQ_NEXT_VAL';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'ORDER_ID_SEQ_NEXT_VAL';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'ORDER_PRODUCT_ID_NEXT_VALUE';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'ORDER_PRD_PRICE_ID_NEXT_VAL';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'ORDER_TOTAL_ID_NEXT_VALUE';
UPDATE SM_SEQUENCER SET SEQ_COUNT = GREATEST(SEQ_COUNT, 100000) WHERE SEQ_NAME = 'STATUS_HIST_ID_NEXT_VALUE';
